//! Go's `unicode` character classes, read from `spec/unicode.txt`
//! (generated by the Go implementation). Rust's `char` methods follow
//! different definitions (`is_alphabetic` accepts Nl, No and combining
//! marks; `is_uppercase` accepts Other_Uppercase), so the places that
//! mirror Go's `unicode.IsLetter` / `IsDigit` / `IsUpper` / `IsPrint` use
//! these tables instead.

use std::collections::BTreeMap;
use std::sync::OnceLock;

const SPEC: &str = include_str!("../../../spec/unicode.txt");

/// Class name → sorted, disjoint inclusive runs `(first, last)`.
fn tables() -> &'static BTreeMap<&'static str, Vec<(u32, u32)>> {
    static TABLES: OnceLock<BTreeMap<&'static str, Vec<(u32, u32)>>> = OnceLock::new();
    TABLES.get_or_init(|| {
        let mut out: BTreeMap<&str, Vec<(u32, u32)>> = BTreeMap::new();
        for line in SPEC.lines() {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let mut f = line.split(' ');
            let (Some(class), Some(lo), Some(hi)) = (f.next(), f.next(), f.next()) else {
                panic!("spec/unicode.txt: bad line {line:?}");
            };
            let hex = |s: &str| {
                u32::from_str_radix(s, 16)
                    .unwrap_or_else(|_| panic!("spec/unicode.txt: bad line {line:?}"))
            };
            out.entry(class).or_default().push((hex(lo), hex(hi)));
        }
        out
    })
}

/// The runs of one class; an unknown class is a build error in the spec.
fn ranges(class: &str) -> &'static [(u32, u32)] {
    tables()
        .get(class)
        .unwrap_or_else(|| panic!("spec/unicode.txt: no class {class}"))
}

/// Binary search for the run that would hold `c`.
fn contains(runs: &[(u32, u32)], c: char) -> bool {
    let u = c as u32;
    let i = runs.partition_point(|&(_, hi)| hi < u);
    runs.get(i).is_some_and(|&(lo, _)| lo <= u)
}

/// Go `unicode.IsLetter` (category L).
pub fn is_letter(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphabetic();
    }
    contains(ranges("letter"), c)
}

/// Go `unicode.IsDigit` (category Nd).
pub fn is_digit(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_digit();
    }
    contains(ranges("digit"), c)
}

/// Go `unicode.IsUpper`.
pub fn is_upper(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_uppercase();
    }
    contains(ranges("upper"), c)
}

/// Go `unicode.IsPrint` (and `strconv.IsPrint`, which shares its
/// definition): L, M, N, P, S and U+0020.
pub fn is_print(c: char) -> bool {
    if c.is_ascii() {
        return matches!(c, ' '..='~');
    }
    contains(ranges("print"), c)
}

#[cfg(test)]
mod tests {
    use super::*;

    // Expected values come from Go 1.27 (unicode.Version 17.0.0).
    #[test]
    fn letter() {
        for c in [
            'a', 'Z', '한', 'ß', 'Σ', 'σ', 'ǅ', 'ª', 'º', 'µ', '\u{1C89}',
        ] {
            assert!(is_letter(c), "{c:?}");
        }
        for c in [
            '_', '1', '²', 'Ⅻ', 'ⅻ', '\u{93F}', '\u{902}', 'Ⓐ', '①', '٣', '\u{378}',
        ] {
            assert!(!is_letter(c), "{c:?}");
        }
    }

    #[test]
    fn digit() {
        for c in ['0', '9', '٣', '𝟘'] {
            assert!(is_digit(c), "{c:?}");
        }
        for c in ['a', '²', 'Ⅻ', '①', '\u{93F}'] {
            assert!(!is_digit(c), "{c:?}");
        }
    }

    #[test]
    fn upper() {
        for c in ['A', 'Z', 'Σ', '\u{1C89}'] {
            assert!(is_upper(c), "{c:?}");
        }
        for c in ['a', 'ß', 'σ', 'ǅ', 'Ⅻ', 'Ⓐ', '한', '_'] {
            assert!(!is_upper(c), "{c:?}");
        }
    }

    #[test]
    fn print() {
        for c in ['a', ' ', '_', '²', 'Ⅻ', '\u{93F}', '한', '😀'] {
            assert!(is_print(c), "{c:?}");
        }
        for c in [
            '\u{378}', '\u{A0}', '\u{3000}', '\u{85}', '\u{180E}', '\u{200B}', '\u{E000}', '\n',
        ] {
            assert!(!is_print(c), "{c:?}");
        }
    }

    /// Rust's `char::is_whitespace` (White_Space) agrees with Go's
    /// `unicode.IsSpace` on every code point, so trimming keeps using it.
    #[test]
    fn whitespace_matches_go_space() {
        let space = ranges("space");
        for u in 0..=0x10FFFFu32 {
            if let Some(c) = char::from_u32(u) {
                assert_eq!(c.is_whitespace(), contains(space, c), "U+{u:04X}");
            }
        }
    }

    /// The ASCII fast paths agree with the tables.
    #[test]
    fn ascii_matches_tables() {
        for u in 0..0x80u8 {
            let c = u as char;
            assert_eq!(is_letter(c), contains(ranges("letter"), c), "{c:?}");
            assert_eq!(is_digit(c), contains(ranges("digit"), c), "{c:?}");
            assert_eq!(is_upper(c), contains(ranges("upper"), c), "{c:?}");
            assert_eq!(is_print(c), contains(ranges("print"), c), "{c:?}");
        }
    }
}
